node -e "
const fs = require('fs');
const html = fs.readFileSync('/tmp/gnews1.html', 'utf8');
const match = html.match(/window\.WBR_init\s*=\s*\[[^]*?\"(https:\/\/[^\"]+)\"/);
if (match) {
  console.log(match[1]);
} else {
  // Let's try general matching for URLs in strings
  const urls = html.match(/\"https?:\/\/[^\"]+\"/g) || [];
  const candidates = urls.map(u => u.replace(/\"/g, '')).filter(u => u.includes('coindesk') || u.includes('cointelegraph') || u.includes('decrypt') || u.includes('theblock') || u.includes('beincrypto') || u.includes('cryptoslate') || u.includes('cryptofox'));
  console.log('Candidates:', candidates);
}
"

node -e "
const fs = require('fs');
const html = fs.readFileSync('/tmp/gnews1.html', 'utf8');
const regex = /\"(https?:\/\/[^\"]+)\"/g;
let match;
const set = new Set();
while ((match = regex.exec(html)) !== null) {
  set.add(match[1]);
}
console.log(Array.from(set).filter(u => !u.includes('gstatic') && !u.includes('google')));
"

